pub async fn authenticate(
    c: &mut AsyncPgConnection,
    headers: &axum::http::HeaderMap,
    kind: &str,
) -> Result<Identity> {
    let t = headers
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|h| h.to_str().ok())
        .and_then(|s| s.strip_prefix("Bearer "))
        .ok_or_else(ApiError::unauthorized)?;
    let identity = decode_token(t, kind)?;
    let rows=sql_query("SELECT data FROM (SELECT jsonb_build_object('id',id) AS data FROM roster_tokens WHERE id=$1 AND subject=$2 AND expires_at>now()) t").bind::<Text,_>(&identity.sid).bind::<Text,_>(&identity.sub).load::<Document>(c).await?;
    if rows.is_empty() {
        return Err(ApiError::unauthorized());
    }
    Ok(identity)
}
