    let user = admin(c, &claims).await?;
    let remaining = (claims.exp as i64 - chrono::Utc::now().timestamp()).max(1);
    let access = token(&claims.sub, "admin", &claims.sid, 3600)?;
    let refresh = token(&claims.sub, "refresh", &claims.sid, remaining)?;
